function infant(age){return ['u3m','3a5m','6a11m'].includes(age);}
function cleft(age){return [
 ['Fissura labiopalatina é uma abertura congênita do lábio e do palato. Pode afetar alimentação, ganho de peso, audição, fala e dentes; o cuidado costuma envolver cirurgia plástica, pediatria, odontologia, fonoaudiologia, nutrição e otorrinolaringologia.','Use o nome preferido “fissura labiopalatina”. Mantenha os retornos mesmo quando a criança parece bem, porque audição, fala e dentição precisam de acompanhamento ao crescer.'],
 [infant(age)?'Alimente na posição mais vertical, com cabeça e pescoço alinhados. Use apenas mamadeira, bico ou técnica ensinada pela equipe; faça pausas e arrote com frequência.':'Siga os exercícios de fala, higiene oral, aparelho ou cuidado odontológico ensinados. Não introduza objeto ou produto na fissura.','Se leite sair pelo nariz, pare, mantenha a criança ereta, limpe suavemente e retome somente quando respirar bem. Não aumente o furo do bico nem improvise placa.'],
 ['Use apenas medicamentos prescritos. Não aplique pomada, cola, talco, anestésico ou receita caseira na boca ou no lábio.','Após cirurgia, cumpra exatamente os cuidados da equipe com ferida, alimentação, protetores de braço e analgesia; não mude dose ou duração.'],
 [infant(age)?'Leite materno continua sendo recomendado, mas a fissura palatina pode impedir sucção eficaz; pode ser necessário leite ordenhado e utensílio especial. Não dilua fórmula.':'Mantenha alimentação adequada à idade e à textura liberada pela equipe, especialmente após cirurgia.','Observe duração das mamadas/refeições, tosse, engasgo, cansaço, mudança de cor, volume aceito e ganho de peso.'],
 ['Dificuldade para respirar, lábios arroxeados, engasgo com alteração de cor, sonolência incomum, recusa persistente, poucas fraldas molhadas, sangramento que não para, abertura da cirurgia, febre ou secreção com mau cheiro exigem avaliação imediata.'],
 ['Reavalie no prazo combinado com a equipe de fissura. Procure antes se mamadas duram muito, há tosse/engasgos, pouco ganho de peso, otites repetidas, dificuldade auditiva, fala pouco compreensível ou problema dentário.','A fissura não é contagiosa. Escola e atividades podem ser mantidas conforme recuperação cirúrgica e orientação da equipe.']
];}
function lupus(){return [
 ['O lúpus juvenil é uma doença autoimune crônica que pode alternar atividade e melhora e afetar pele, articulações, rins, sangue, pulmões, coração ou sistema nervoso. Mesmo sem sintomas, consultas e exames continuam necessários.','Registre febre, cansaço, dor ou inchaço articular, manchas, feridas na boca, queda de cabelo, dor no peito, pressão, peso, inchaço e alterações na urina.'],
 ['Proteja do sol diariamente com roupa, chapéu, sombra e protetor orientado para a idade; luz ultravioleta pode favorecer atividade da doença.','Equilibre escola, sono, atividade física gradual e pausas. Avise a escola sobre fadiga, proteção solar e plano de emergência sem afastar a criança desnecessariamente.'],
 ['Dê exatamente os medicamentos prescritos e não interrompa corticoide ou imunossupressor de repente. Não inicie anti-inflamatório, vitamina, suplemento ou erva sem confirmar com a reumatologia.','Combine vacinas, procedimentos e tratamento de infecções com a equipe, especialmente se houver imunossupressão. Mantenha exames de sangue, urina e olhos quando solicitados.'],
 ['Mantenha alimentação variada e hidratação habitual, salvo restrição individual por rim, pressão ou medicamento. Evite dieta “anti-lúpus”, excesso de sal e suplementos sem indicação.'],
 ['Falta de ar, dor no peito, convulsão, confusão, desmaio, fraqueza súbita, dor de cabeça intensa diferente do habitual, sangramento importante, pouca urina, urina com sangue/espuma, inchaço rápido, dor abdominal intensa ou febre com prostração durante imunossupressão exigem atendimento imediato.'],
 ['Cumpra reumatologia e exames mesmo na remissão. Procure antes por febre persistente, nova erupção, feridas, dor/inchaço articular, perda de peso, pressão alta, edema, mudança na urina ou efeito adverso.','A doença não é contagiosa. Ajustes de escola e esporte devem ser individualizados, preservando participação quando clinicamente segura.']
];}
function malaria(row,age){const fal=row.kind==='falciparum';return [
 [(fal?'A malária por P. falciparum pode piorar rapidamente e ser fatal sem tratamento oportuno.':'A malária por P. vivax pode causar recaídas e também evoluir com gravidade.')+' Se o diagnóstico foi confirmado e o tratamento ainda não começou, procure hoje o serviço que trata malária.','Meça temperatura, observe consciência, respiração, vômitos, sangramento e urina. Informe viagens ou residência em área de transmissão e leve o resultado do exame.'],
 ['Repouso conforme tolerância. Use mosquiteiro, telas, roupa que cubra braços e pernas e repelente apropriado à idade, seguindo o rótulo.','Não há transmissão pelo contato casual; a prevenção habitual é contra a picada do mosquito. Não compartilhe agulhas.'],
 ['Use somente o esquema entregue pelo SUS e complete todas as etapas, mesmo após a febre melhorar. Não compartilhe, repita, troque ou combine antimalárico por conta própria.','A escolha depende de espécie, idade, peso, gravidade e outras condições.'+(fal?' P. falciparum exige esquema específico e tratamento imediato.':' Para cura radical de P. vivax, a equipe deve conferir segurança, incluindo idade e avaliação de G6PD quando indicada; alguns medicamentos não podem ser usados em certas populações.'),],
 [infant(age)?'Mantenha leite materno ou fórmula em pequenas ofertas frequentes, sem diluir. Não force se estiver sonolento, vomitando ou com dificuldade para respirar.':'Ofereça água e líquidos seguros em pequenas quantidades frequentes e refeições leves conforme aceitação.','Vômitos repetidos, recusa de líquidos, boca seca ou pouca urina exigem reavaliação rápida.'],
 ['Convulsão, confusão ou sonolência difícil de despertar, prostração extrema, desmaio, dificuldade para respirar, sangramento, pele/olhos amarelados, vômitos repetidos, pouca ou nenhuma urina, incapacidade de beber ou piora rápida exigem hospital imediatamente. Crianças pequenas têm maior risco de gravidade.'],
 ['Retorne no prazo definido para confirmar resposta e concluir o seguimento. Volte antes se a febre não melhora como esperado, retorna após melhora ou qualquer sinal de alarme aparece.'+(fal?' Não espere a próxima crise de febre.':' P. vivax pode reaparecer por formas dormentes no fígado; febre recorrente exige novo exame e revisão do plano.'),'A criança pode voltar à escola quando estiver sem febre, bem disposta e liberada; mantenha proteção contra mosquitos em área de transmissão.']
];}
function dermal(){return [
 ['Melanocitose dérmica congênita é uma marca de nascença plana azul ou azul-acinzentada, mais comum em nádegas e costas. É benigna, não dói e costuma clarear ao longo da infância.','Peça que localização, tamanho e aspecto sejam registrados no prontuário ou caderneta, pois pode parecer hematoma. Marcas novas depois do nascimento não devem ser automaticamente atribuídas a ela.'],
 ['Não esfregue, massageie nem tente clarear. Fotografe com data se a equipe orientar acompanhamento; compare apenas em luz semelhante.'],
 ['Não precisa de medicamento. Não aplique clareador, ácido, corticoide ou receita caseira; podem causar queimadura, infecção ou cicatriz.'],
 ['Não exige dieta nem mudança de líquidos. Mantenha alimentação habitual adequada à idade.'],
 ['Procure atendimento se houver nova mancha sem explicação, dor, inchaço, calor, sangramento, febre, muitos hematomas, alteração rápida de cor/tamanho ou suspeita de trauma.'],
 ['Reavalie em consulta habitual. Marcas muito extensas, que crescem, são elevadas, aparecem em local incomum ou próximas à boca merecem avaliação pediátrica/dermatológica.','Não é contagiosa e não limita banho, toque, escola, esporte ou vacinação.']
];}
function medullo(age){return [
 ['Meduloblastoma é um tumor maligno do cérebro, geralmente de crescimento rápido, que pode se espalhar pelo líquido ao redor do cérebro e da medula. O tratamento é individualizado por equipe de neuro-oncologia pediátrica.','Mantenha à mão o contato 24 horas da equipe, lista de medicamentos, alergias, acesso venoso e plano para febre. Observe equilíbrio, marcha, fala, visão, força, comportamento e vômitos.'],
 ['Previna quedas: supervisione banho e escadas e use apoio orientado pela fisioterapia. Siga reabilitação, cuidados da ferida e do acesso venoso conforme ensinados.','Durante tratamento, lave as mãos, evite contato próximo com pessoas doentes e confirme com a equipe antes de vacina, procedimento dentário, viagem ou retorno escolar.'],
 ['Dê apenas o tratamento prescrito. Não ajuste antiepiléptico, corticoide, quimioterapia, analgésico ou antiemético sem falar com a equipe; não interrompa de repente.','Durante quimioterapia, temperatura de 38 °C ou mais exige contato imediato antes de antitérmico, porque infecção pode ser grave e a febre pode ser mascarada.'],
 [infant(age)?'Mantenha leite materno ou fórmula e a técnica segura orientada. Observe engasgo, cansaço e ganho de peso.':'Ofereça pequenas refeições e líquidos conforme tolerância e plano nutricional.','Não force se houver sonolência, vômitos ou engasgo; procure orientação se a ingestão cair ou houver perda de peso.'],
 ['Dor de cabeça intensa ou progressiva, vômitos repetidos sobretudo pela manhã, sonolência ou confusão, convulsão, desmaio, nova fraqueza, perda súbita de equilíbrio, dificuldade para falar/engolir/respirar, alteração visual importante, febre de 38 °C ou mais durante tratamento ou problema no cateter exigem ação imediata.'],
 ['Cumpra oncologia, imagem, exames, audição, endocrinologia, cognição e reabilitação no cronograma, mesmo quando está bem. Procure antes por novos sintomas neurológicos, febre, perda de peso, dor ou efeito adverso.','Escola e atividade física devem seguir plano individual, com adaptações para fadiga, equilíbrio, aprendizagem e risco de infecção.']
];}
function hirsch(age){return [
 ['Na doença de Hirschsprung, falta a rede de nervos em parte do intestino grosso, dificultando a passagem das fezes. O tratamento costuma ser cirúrgico, mas constipação, escapes e enterocolite podem ocorrer antes ou depois da operação.','Observe evacuações, distensão abdominal, vômitos, febre, energia, alimentação e ganho de peso. Se houver estoma, siga o plano da equipe e observe cor, pele e débito.'],
 ['Siga apenas a irrigação retal e os cuidados pós-operatórios ensinados pela cirurgia. Não use termômetro retal, supositório, enema ou estimulação anal sem autorização.','Não tente “desobstruir” com massagem forte. Registre dias sem evacuar, consistência e sintomas associados.'],
 ['Use somente medicamentos, laxantes, antibióticos ou irrigação prescritos. Não repita plano antigo diante de febre, diarreia, vômito ou barriga inchada: enterocolite precisa de avaliação hospitalar.'],
 [infant(age)?'Mantenha leite materno ou fórmula conforme o plano; não dilua fórmula nem dê chá/água ao bebê sem orientação.':'Após recuperação cirúrgica, a maioria não precisa de dieta especial; siga o plano da cirurgia/nutrição e ofereça líquidos adequados à idade.','Recusa, vômito verde, distensão, perda de peso ou menos urina exigem avaliação.'],
 ['Barriga inchando, febre, diarreia aquosa ou explosiva, vômitos, falta de energia, sangramento retal, choque, vômito verde, dor intensa ou incapacidade de eliminar fezes/gases exigem hospital imediatamente: enterocolite pode ser fatal.'],
 ['Cumpra os retornos com cirurgia pediátrica. Procure antes por constipação persistente, escapes, distensão, vômitos, baixo ganho de peso, problema no estoma ou dificuldade para seguir o plano.','Creche/escola deve conhecer o acesso ao banheiro, cuidados do estoma e sinais de enterocolite; a condição não é contagiosa.']
];}
